      SUBROUTINE PARTLSCC     CALCULATES PARTIALS OF FIRST-ORDER MATRIX OF A SINGLE BEAMC     ELEMENT WITH RESPECT TO THE VARIED QUANTITYCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'COCOM.CIN'      INCLUDE 'COP.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM0C.CIN'      INCLUDE 'ELM0D.CIN'      INCLUDE 'ELM0E.CIN'      INCLUDE 'ELM1A.CIN'      INCLUDE 'ELM2B.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM5A.CIN'      INCLUDE 'ELM5B.CIN'      INCLUDE 'ELM6.CIN'      INCLUDE 'ELM7B.CIN'      INCLUDE 'ELM8A.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM10E.CIN'      INCLUDE 'ELM13A.CIN'      INCLUDE 'ELM14A.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM15C.CIN'      INCLUDE 'ELM16B.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'ELM20.CIN'      INCLUDE 'ELM42.CIN'      INCLUDE 'ETACOM.CIN'      INCLUDE 'ETAP.CIN'      INCLUDE 'INDBND.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'R.CIN'      INCLUDE 'SI.CIN'      INCLUDE 'SVP.CIN'CC ---------------------------------------------------------------------C      GO TO ( 100, 200, 300, 400, 500, 600, 700, 800,5020,5020,     1       5020,1200,5020,1400,5020,5020,5020,1800,1900,2000,     2       5020,5020,5020,5020,2500,5020,2700,2800,2800,5020,     3       5020,5020,5020,3400,3500,3500,3700,5020,5020,5020,     4       5020,4200,4300,5020,5020,5020,5020,5020), TYPECC     1. -- BEAMC  100 CALL DBEAMS      GO TO 5020CC     2. -- POLE FACE ROTATIONC  200 IF (JV .EQ. 1) GO TO 210      IF (JV .EQ. 5) GO TO 220      IF (JV .EQ. 4) GO TO 5000      GO TO 5020C  210 CALL DFRINJ      GO TO 5000C  220 CALL DFRINB      GO TO 5000CC     3. -- DRIFT SPACEC  300 LINEAR = .FALSE.      LV = DPARM*UNITI(8)      RV(1,2) = LV      RV(3,4) = LV      IF (RI .EQ. 0.0 .AND. SM .EQ. 0.0) THEN        RV(5,6) = 0.0      ELSE        RV(5,6) = SM**2*LV/(RI**2 + SM**2)      ENDIF      GO TO 5000CC     4. -- BENDING MAGNETC  400 CALL DBENDI      GO TO 5000CC     5. -- QUADRUPOLEC  500 LINEAR = .FALSE.      IF (TYPEC .EQ. 20) GO TO 560      IF (JV .EQ. 1) GO TO 510      IF (JV .EQ. 2 .OR. JV .EQ. 3 .OR. JV .EQ. 4 .OR. JV .EQ. 5)      1    GO TO 520      IF (JV .EQ. NTILT) GO TO 540      GO TO 5020C  510 LV = DPARM*UNITI(8)      LVE = LV      JQUAD = 1      KQ2 = KX2      CALL DFOL      JQUAD = 3      KQ2 = KY2      CALL DFOL      GO TO 5000C  520 IB = IPTOJ(2)      IAP = IPTOJ(3)      IG = IPTOJ(4)      IK1 = IPTOJ(5)      IF (JV .EQ. 2 .AND. IB .NE. 0) KVK = 0.5*UNITI(9)/(AP*PREF)      IF (JV .EQ. 3 .AND. IAP .NE. 0)      1    KVK = - 0.5*UNITI(1)*B/(AP**2*PREF)      IF (IG .NE. 0) KVK = 0.5*UNITI(9)/(PREF*UNITI(1))      IF (IK1 .NE. 0) KVK = 0.5/UNITI(8)**2      KVK = KVK*DPARM      JQUAD = 1      KQ2 = KX2      CALL DFOCUS      JQUAD = 3      KQ2 = KY2      KVK = - KVK      CALL DFOCUS      KVK = - KVK      GO TO 5000C  540 IF (JV .EQ. NTILT .AND. REFER) THEN        CALL DSROTR      ENDIF      GO TO 5000C  560 IF (JV .EQ. NTILT) THEN        CALL DSROTN        GO TO 5000      ELSE        GO TO 5020      ENDIFCC     6. -- UPDATEC  600 IF (TYPEC .EQ. 8) THEN        LTAB = MOD(TYT/10,10)        IF (LTAB .EQ. 0) THEN          IF (RORC .LE. 2) CALL WOBBLE        ENDIF      ENDIF      GO TO 5020CC     7. -- BEAM CENTROID SHIFTC  700 LINEAR = .FALSE.      SIGG = DPARM      NV2 = IABS(NV2)      IF (.NOT. CVP(NV2)) THEN        DO 710 J = 1, 6        COV(J,NV2) = 0.0  710   CONTINUE      ENDIF      COV(JV,NV2) = COV(JV,NV2) + SIGG*UBEAM(JV)      CVP(NV2) = .TRUE.      GO TO 5020CC     8. -- MAGNET MISALIGNMENTC  800 LTAB = MOD(TYT/10,10)      IF (LTAB .EQ. 0) THEN        IF (RORC .LE. 3) CALL WOBBLE      ENDIF      GO TO 5020CC     12. -- CORRELATIONS IN BEAM ELLIPSEC 1200 SIGG = DPARM      NV2 = IABS(NV2)      IF (NORD3 .GE. 1) THEN        K = (3 + INT(SQRT(8.0E0*FLOAT(JV) - 6.99E0)))/2        J = JV - (K-1)*(K-2)/2        DSIG = SIGG*SQRT(SI(J,J)*SI(K,K))        IF (.NOT. SVP(NV2)) THEN          DO 1210 J1 = 1, 6          DO 1210 J2 = 1, 6          SV(J1,J2,NV2) = 0.0 1210     CONTINUE        ENDIF        SV(J,K,NV2) = SV(J,K,NV2) + DSIG        SV(K,J,NV2) = SV(J,K,NV2)        SVP(NV2) = .TRUE.      ENDIF      GO TO 5020CC     14. -- ARBITRARY MATRIXC 1400 RV(J1,JV) = DPARM*UBEAM(J1)/UBEAM(JV)      GO TO 5000CC     18. -- SEXTUPOLEC 1800 IF (TYPEC .EQ. 20) GO TO 1820      IF (JV .EQ. NTILT) CALL DSROTR      GO TO 5000C 1820 IF (JV .EQ. NTILT) THEN        CALL DSROTN        GO TO 5000      ELSE        GO TO 5020      ENDIFCC     19. -- SOLENOIDC 1900 LINEAR = .FALSE.      CALL DSOLEN      GO TO 5000CC     20. -- BEAM ROTATIONC 2000 LINEAR = .FALSE.      IF (.NOT. REFER) CALL DSROTN      GO TO 5020CC     25. -- OCTUPOLEC 2500 IF (TYPEC .EQ. 20) GO TO 2520      IF (JV .EQ. NTILT) CALL DSROTN      GO TO 5000C 2520 IF (JV .EQ. NTILT .AND. REFER) THEN        CALL DSROTR        GO TO 5000      ELSE        GO TO 5020      ENDIFCC     27. -- ACCELERATOR FUNCTION ETAC 2700 LINEAR = .FALSE.      SIGG = DPARM      NV2 = IABS(NV2)      IF (.NOT. EVP(NV2)) THEN        DO 2710 J = 1, 6        ETAV(J,NV2) = 0.0 2710   CONTINUE      ENDIF      ETAV(JV,NV2) = ETAV(JV,NV2) + SIGG*UBEAM(JV)      EVP(NV2) = .TRUE.      GO TO 5020CC     28. -- RBENDC         ORC     29. -- SBENDC 2800 IF (TYPEC .EQ. 20) GO TO 2840      IF (TYPEC .EQ. 2) GO TO 2820      CALL DBENDI      GO TO 5000C 2820 IF (JV .EQ. NB .OR. JV .EQ. NE1 .OR. JV .EQ. NE2) GO TO 2825      IF (JV .EQ. NL .OR. JV .EQ. NBV .OR. JV .EQ. NRHO     1    .OR. JV .EQ. NANG) GO TO 2830      IF (JV .EQ. NH1 .OR. JV .EQ. NH2) GO TO 5000      GO TO 5020C 2825 CALL DFRINJ      GO TO 5000C 2830 IE1 = IPTOJ(NE1)      IE2 = IPTOJ(NE2)      IF ((TYPE .EQ. 29 .AND. JV .EQ. NANG)     1    .OR. TYPE .EQ. 28 .AND. ((BEFORE .AND. IE1 .NE. 0))     2    .OR. (.NOT. BEFORE .AND. IE2 .NE. 0)) THEN        CALL DFRINB      ELSE IF (TYPE .EQ. 28) THEN        CALL DFRINR      ENDIF      GO TO 5000C 2840 IF (JV .EQ. NTILT .AND. .NOT. REFER) THEN        CALL DSROTR        GO TO 5000      ELSE        GO TO 5020      ENDIFCC     34. -- PLASMA LENSC 3400 LINEAR = .FALSE.      IF (JV .EQ. 1) GO TO 3410      IF (JV .EQ. 2 .OR. JV .EQ. 3 .OR. JV .EQ. 4 .OR. JV .EQ. 5)      1    GO TO 3420              GO TO 5020C 3410 LV = DPARM*UNITI(8)      LVE = LV      JQUAD = 1      CALL DFOL      JQUAD = 3      CALL DFOL      GO TO 5000C 3420 IB = IPTOJ(2)      IAP = IPTOJ(3)      IG = IPTOJ(4)      IK1 = IPTOJ(5)      IF (JV .EQ. 2 .AND. IB .NE. 0) KVK = 0.5*UNITI(9)/(AP*PREF)      IF (JV .EQ. 3 .AND. IAP .NE. 0)      1    KVK = - 0.5*UNITI(1)*B/(AP**2*PREF)      IF (IG .NE. 0) KVK = 0.5*UNITI(9)/(PREF*UNITI(1))      IF (IK1 .NE. 0) KVK = 0.5/UNITI(8)**2      KVK = KVK*DPARM      JQUAD = 1      CALL DFOCUS      JQUAD = 3      CALL DFOCUS      GO TO 5000CC     35. -- HKICK -- HORIZONTAL VERNIERC                     ORC     36. -- VKICK -- VERTICAL VERNIERC 3500 IF (TYPEC .EQ. 20) GO TO 3540      IF (TYPEC .EQ. 2) GO TO 3530      IF (JV .LT. 1 .OR. JV .GT. 5) GO TO 5020      IF (JV .EQ. 2 .OR. JV .EQ. 3 .OR. JV .EQ. 4) GO TO 3510      IF (JV .EQ. 5) GO TO 3520C      DCOV = .TRUE.      DAL = DPARM*B*UNITI(8)/PREF      CODV(1) = - 0.5*DAL*L      CODV(2) = - DAL      RV(1,6) = 0.5*DAL*L      RV(2,6) = DAL      GO TO 5000C 3510 IB = IPTOJ(2)      IANG = IPTOJ(3)      IK = IPTOJ(4)            IF (IB .NE. 0.0) DAL = DPARM*L*UNITI(9)/PREF      IF (IANG .NE. 0.0) DAL = DPARM*UNITI(7)      IF (IK .NE. 0.0) DAL = - DPARM*UNITI(7)      DCOV = .TRUE.      CODV(1) = - 0.5*DAL*L      CODV(2) = - DAL      RV(1,6) = 0.5*DAL*L      RV(2,6) = DAL      GO TO 5000C 3520 IF (REFER) THEN        CALL DSROTR        CALL DSROTC      ENDIF      GO TO 5000C 3530 GO TO 5020C 3540 IF (JV .EQ. NTILT .AND. .NOT. REFER) CALL DSROTN      GO TO 5000CC     37. -- ALIGNMENT MARKERC 3700 IF (TYPEC .EQ. 8) THEN        LTAB = MOD(TYT/10,10)        IF (LTAB .EQ. 0) THEN          IF (RORC .LE. 2) CALL WOBBLE        ENDIF      ENDIF      GO TO 5020CC     42. -- KICKER -- VERNIER IN BOTH PLANESC 4200 IF (TYPEC .EQ. 20) GO TO 4240      IF (TYPEC .EQ. 2) GO TO 4220      IF (JV .NE. 2 .AND. JV .NE. 3) GO TO 5020      IKH = IPTOJ(2)      IKV = IPTOJ(3)      IF (IKH .NE. 0.0 .OR. IKV .NE. 0.0) DAL = - UNITI(7)      IF (AL .NE. 0.0) DAL = DAL*HAL/AL      DCOV = .TRUE.      CODV(1) = - 0.5*DAL*L      CODV(2) = - DAL      RV(1,6) = 0.5*DAL*L      RV(2,6) = DAL      GO TO 5000C 4220 GO TO 5020C 4240 IF (JV .NE. 2 .AND. JV .NE. 3) GO TO 5020      LINEAR = .FALSE.      IF (REFER) GO TO 5020      IF (AL .NE. 0.0) THEN        IF (JV .EQ. 2) THEN          DTH = VAL/AL**2        ELSE          DTH = - HAL/AL**2        ENDIF      ELSE        DTH = 0.0      ENDIF      DTH = DTH*UNITI(7)      DPARM = DTH/UNITI(13)      CALL DSROTN      GO TO 5020CC     43. -- REFERENCE COORDINATE SYSTEM SHIFTC 4300 LINEAR = .FALSE.      SIGG = DPARM      NV2 = IABS(NV2)      IF (.NOT. CVP(NV2)) THEN        DO 4310 J = 1, 6        COV(J,NV2) = 0.0 4310   CONTINUE      ENDIF      COV(JV,NV2) = COV(JV,NV2) + SIGG*UBEAM(JV)      CVP(NV2) = .TRUE.      GO TO 5020CC     RETURNC 5000 IF (NORD1 .GE. 2) CALL PARSEC      IF (REFER .AND. TOTROT .NE. 0.0 .AND. .NOT. RSYM) CALL ROTAT1(NV2) 5020 RETURN      END